import 'package:meta/meta.dart';import '../../../../../../../Core/Models/cart_itemes.dart';@immutableclass CartStates {  final bool? loading;  final String? message;  final String? error;  final bool? success;  final CartItemsModel? cartItems;  const CartStates({     this.loading,     this.message ,    this.error,    this.success,    this.cartItems,  });  CartStates copyWith({    final bool? loading,    final String? message,    final String? error,    final bool? success,    final CartItemsModel? cartItems,  }) {    return CartStates(      loading: loading ?? this.loading,      message: message ?? this.message,      error: error ?? this.error,      success: success ?? this.success,      cartItems: cartItems ?? this.cartItems,    );  }}